// src/components/CompanyForm.js
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "../index.css";

const CompanyForm = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    company_id: "",
    user_id: "",
    company_name: "",
    company_description: "",
    country: "",
    city: "",
    company_size: "",
    embedding_vector_id: "",
    created_at: "",
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Save company profile locally for now (you can send to backend later)
    const existing = JSON.parse(localStorage.getItem("companyProfiles") || "[]");
    existing.push(formData);
    localStorage.setItem("companyProfiles", JSON.stringify(existing));

    alert("Company profile created!");
    localStorage.setItem('profileCreated', 'true');
    const cu = JSON.parse(localStorage.getItem('currentUser') || '{}');
    cu.role = 'company';
    localStorage.setItem('currentUser', JSON.stringify(cu));

    navigate("/dashboard");
  };

  return (
    <div className="form-container">
      <h1 className="heading">SoftScale</h1>
      <div className="form-box">
        <h2>Company Admin Profile</h2>

        <form onSubmit={handleSubmit}>
          <input
            name="company_id"
            placeholder="Company ID (integer)"
            value={formData.company_id}
            onChange={handleChange}
          />
          <input
            name="user_id"
            placeholder="User ID (integer)"
            value={formData.user_id}
            onChange={handleChange}
          />
          <input
            name="company_name"
            placeholder="Company Name"
            value={formData.company_name}
            onChange={handleChange}
            required
          />
          <textarea
            name="company_description"
            placeholder="Company Description"
            value={formData.company_description}
            onChange={handleChange}
            rows={4}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", marginTop: 8 }}
          />
          <input
            name="country"
            placeholder="Country"
            value={formData.country}
            onChange={handleChange}
          />
          <input
            name="city"
            placeholder="City"
            value={formData.city}
            onChange={handleChange}
          />
          <input
            name="company_size"
            placeholder="Company Size (e.g., 50-200)"
            value={formData.company_size}
            onChange={handleChange}
          />
          <input
            name="embedding_vector_id"
            placeholder="Embedding Vector ID (bigint)"
            value={formData.embedding_vector_id}
            onChange={handleChange}
          />
          <input
            name="created_at"
            placeholder="Created At (YYYY-MM-DD)"
            value={formData.created_at}
            onChange={handleChange}
          />

          <button type="submit" className="btn-primary" style={{ marginTop: 12 }}>
            Create Company
          </button>
        </form>
      </div>
    </div>
  );
};

export default CompanyForm;
